def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the grid's regularly-spaced separator rows and columns. In these
    # puzzles the separator color is the color most common on lines at the
    # repeating interval; the intervening areas are solid background blocks.
    def line_signature(axis, i):
        if axis == 0:
            return tuple(grid[i])
        return tuple(grid[r][i] for r in range(h))

    def get_period(axis, n):
        best = None
        for p in range(2, min(10, n)):
            # Score periodicity of line signatures, favoring a common signature.
            sigs = [line_signature(axis, i) for i in range(n)]
            score = sum(sigs[i] == sigs[i % p] for i in range(n))
            if best is None or score > best[0]:
                best = score, p
        return best[1]

    ph = get_period(0, h)
    pw = get_period(1, w)

    # Separator lines are every period cells; sample the color where each
    # separator row and separator column meet. Ignore the outermost border
    # when it merely frames the pattern.
    rows = list(range(0, h, ph))
    cols = list(range(0, w, pw))
    if len(rows) > 2:
        rows = rows[1:]
    if len(cols) > 2:
        cols = cols[1:]

    out = []
    for r in rows:
        out.append([grid[r][c] for c in cols])
    return out
