def transform(grid):
    h, w = len(grid), len(grid[0])

    # Identify the regularly spaced separator rows and columns by looking for
    # lines whose pattern differs from the repeated solid interior lines.
    def find_lines(axis):
        n = h if axis == 0 else w
        signatures = []
        for i in range(n):
            signatures.append(tuple(grid[i]) if axis == 0 else
                              tuple(grid[r][i] for r in range(h)))
        for period in range(2, min(10, n)):
            if sum(signatures[i] == signatures[i % period] for i in range(n)) >= n - 2:
                return list(range(0, n, period))
        return []

    rows, cols = find_lines(0), find_lines(1)
    if len(rows) < 2 or len(cols) < 2:
        return [[grid[0][0]]]

    # Most cells between separators have the same fill color.
    from collections import Counter
    interiors = []
    for r in range(h):
        for c in range(w):
            if r not in rows and c not in cols:
                interiors.append(grid[r][c])
    base = Counter(interiors).most_common(1)[0][0]

    # Each separator intersection carries either a marker color or the
    # ordinary base color. These intersections form the decoded image.
    return [[grid[r][c] if grid[r][c] != 4 else base for c in cols[1:]]
            for r in rows[1:]]
